def catalan_number(n):
    # Base case: the first Catalan number is 1
    if n == 0:
        return 1
    # Initialize the result
    result = 0
    # Calculate the nth Catalan number using the formula
    for i in range(n):
        result += catalan_number(i) * catalan_number(n - i - 1)
    return result

def hexagonal_num(n):
    # Calculate the nth hexagonal number using the formula
    return n * (2 * n - 1)

