def get_median(arr1, arr2, n):
    # Initialize variables to store the median
    i = j = 0
    m1 = m2 = 0

    # Merge the two arrays until we reach the middle elements
    for _ in range(n):
        m1 = m2
        if i < n and j < n:
            if arr1[i] < arr2[j]:
                m2 = arr1[i]
                i += 1
            else:
                m2 = arr2[j]
                j += 1
        elif i < n:
            m2 = arr1[i]
            i += 1
        else:
            m2 = arr2[j]
            j += 1

    # Return the median
    return (m1 + m2) / 2

